		contract_rpt_menu.add_command(label='Variable opex per mmcf',
									  command=lambda: self.getModelRules("VARIABLE_OPEX_PER_MMCF"), underline=0)
		contract_rpt_menu.add_command(label='Capex redevelopment',
									  command=lambda: self.getModelRules("CAPEX_REDEVELOPMENT"), underline=0)
		#
		pulldown.add_cascade(label='Parameters...', menu=contract_rpt_menu, underline=0)
		pulldown.add_command(label='Capex Allocation', command=lambda: self.getCapex("CAPEX_ALLOC"))
