	def jobMenu(self):
		pulldown = Menu(self.menubar)
		pulldown.add_command(label='Create Models', command=lambda: self.createModels("Create Models"),
							 accelerator='Ctrl+M')
		pulldown.add_separator()
		pulldown.add_command(label='Analyze Model Data', command=lambda: self.analyzeModels(), accelerator='Ctrl+Z')
		pulldown.add_separator()
		pulldown.add_command(label='Asset Analytics', command=lambda: self.assetAnalytics(), accelerator='Ctrl+A')
		pulldown.add_separator()
		pulldown.add_command(label='Error Log', command=lambda: self.createLogFile1("ERROR"))
		pulldown.add_command(label='Error Log Find', command=lambda: self.errorLogRange())
		pulldown.add_command(label='Error Log Clear', command=lambda: self.clearErrorLog())
		pulldown.add_separator()
