		pulldown.add_command(label='Error Log Exceptions Export', command=lambda: self.errLogException('E'))
		pulldown.add_separator()
		pulldown.add_command(label='Parameter Track Log', command=lambda: self.createLogFile1("PARAM_TRACK"))
		pulldown.add_command(label='Parameter Track Find', command=lambda: self.parameterTrackFind())
		pulldown.add_command(label='Parameter Track Clear', command=lambda: self.parameterTrackClear())
		pulldown.add_command(label='Parameter Track Compare', command=lambda: self.parameterTrackCompare())
		pulldown.add_separator()
		pulldown.add_command(label='Gap after intial drilling', command=lambda: self.createGapReport())
		pulldown.add_command(label='Zeroes after initial production', command=lambda: self.createHardZeroReport())
		self.menubar.add_cascade(label='Jobs', underline=0, menu=pulldown)
	
