	def parameterTrackClear(self):
		try:
			self.error_msg.set("Clearing PARAMETER TRACK")
			if not self.autorun:
				self.update_idletasks()
			stime = time.time()
			curr = self.curr
			loginName = os.environ.get("USERNAME")
			userName = getpass.getuser()
			sqlStatement = "DELETE FROM param_track"
			curr.execute(sqlStatement)
			curr.execute("commit;")
			self.error_msg.set("AN ERROR OCCURRED")
		except:
			# an error occurred
			self.error_msg.set("Finished Clearing PARAMETER TRACK")
		if not self.autorun:
			self.update_idletasks()
	
