	# --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	def FQC(self, ch):
		ret_val = ch
		if ch is None:
			ret_val = ""
		return ret_val
	
	# --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	def FQI(self, iv):
		ret_val = iv
		if iv is None:
			ret_val = 0
		return ret_val
	
