	# --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	def translateUnits(self, mCur, mCommodity, val, beginUnits, endUnits):
		ret_val = val
		sql_statement = "SELECT " + endUnits + " FROM unit_conversion WHERE UPPER(commodity)=%s and UPPER(unit) =%s ;"
		# print '%s - %s:' % (self.AssetId, self.model_section), sql_statement
		mCur.execute(sql_statement, (mCommodity, beginUnits))
		r2 = mCur.fetchall()
		for row in r2:
			ret_val = row[0] * val
		return ret_val
	
	# --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	def check_unit(self, mCur, mUnit, toUnit):
		ret_val = 0
		if len(mUnit) > 0:
			# convert for this commodity
			sql_statement = '''SELECT  unit FROM unit_equals WHERE UPPER(Unit) = %s and UPPER(base_unit) = %s ;'''
			mCur.execute(sql_statement, (mUnit.upper().strip(), toUnit.upper().strip()))
			r2 = mCur.fetchall()
			for datarow in r2:
				ret_val = 1
		return ret_val
	
	# --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	def convert_to_unit(self, mCur, currCommodity, fromUnit, toUnit):
		ret_val = 0
		commodity = currCommodity.upper().strip()
		from_unit = fromUnit.upper().strip()
		base_unit = toUnit.upper().strip()
		if commodity:
			sql_select = 'SELECT factor FROM unit_equals WHERE UPPER(commodity)="{}" and UPPER(unit)="{}" and UPPER(base_unit)="{}"'.format(commodity, from_unit, base_unit)
			if mCur.execute(sql_select):
				ret_val = float(mCur.fetchone()[0])
		return ret_val
	
