		if len(mErrorType.strip()) > 0:
			sql_statement += "errorType LIKE '" + mErrorType + "%' AND "
		if len(mComment.strip()) > 0:
			sql_statement += "comment = '" + mComment + "' AND "
		# strip off the and
		if len(sql_statement) > 0:
			# comment was made
			sql_statement = "SELECT * FROM error_log_exception WHERE " + sql_statement[:-4]
			# print '%s - %s:' % (self.AssetId, self.model_section), sql_statement
			mCur.execute(sql_statement)
			r2 = mCur.fetchall()
			for datarow in r2:
				# Exception found
				ret_val = True
		return ret_val
	
