	def getCommodityUnits(self, mCur, mCommodity, mPriceCode):
		mBaseUnit = ""
		mStandardUnit = ""
		unitsChosen = ""
		ret_val = 1
		mFactor = 1
		sql_statement = 'SELECT unit FROM prices where price_code = %s '
		mCur.execute(sql_statement + ";", (mPriceCode,))
		r2 = mCur.fetchall()
		for row in r2:
			mBaseUnit = row[0]
		if len(mBaseUnit) > 0:
			sql_statement = 'SELECT unit FROM prices_standard where UPPER(commodity) = %s '
			mCur.execute(sql_statement + ";", (mCommodity.upper(),))
			r2 = mCur.fetchall()
			for row in r2:
				mStandardUnit = row[0]
			if len(mStandardUnit) > 0:
				if mStandardUnit.count("/") > 0:
					mPos = mStandardUnit.index("/")
					if mPos > 0:
						unitsChosen = mStandardUnit[mPos + 1:]
			if len(unitsChosen) > 0:
				if unitsChosen == 'bbl':
					#
					col_name = 'usd_bbl'
				elif unitsChosen == 'mcf':
					#
					col_name = 'usd_mcf'
				else:
					col_name = ''
				if len(col_name) > 0 and len(mBaseUnit) > 0:
					sql_statement = 'SELECT ' + col_name + ' FROM unit_conversion where upper(commodity) = %s  and unit = %s'
					mCur.execute(sql_statement + ";", (mCommodity.upper(), mBaseUnit))
					r2 = mCur.fetchall()
					for row in r2:
						ret_val = row[0]
		return ret_val
	
