			sql_query += 'AND (asset_id=%s OR asset_id="" OR asset_id IS NULL OR asset_id=0) AND (resource_type="%s" OR resource_type="" OR resource_type IS NULL) '
			sql_query += 'AND (facility_type="%s" OR facility_type="" OR facility_type IS NULL) AND (constituent="%s" OR constituent="" OR constituent IS NULL) '
