	def return_last_index(self, arr, val):
		ret_val = 0
		pos = 0
		one_found = False
		reps = arr.count(val)
		if reps == 0:
			ret_val = 0
		elif reps == 1:
			ret_val = arr.index(val)
		else:
			last_pos = 0
			reps_found = 0
			for i in range(0, len(arr)):
				if arr[i] == val:
					reps_found += 1
					last_pos = i
					if reps == reps_found:
						break
			ret_val = last_pos
		return ret_val
	
