	def load_bm(self, cur, pCode):
		# if pCode == "WTI" or pCode == "BRENT" or pCode == "URALS" or pCode == "HH":
		cur.execute("USE globaldata")
		sql_statement = "SELECT id FROM PRICES WHERE PRICE_CODE = %s  ;"  # <-- add facility_type
		cur.execute(sql_statement, (pCode,))
		#
		rowOne = cur.fetchone()
		if rowOne is not None:
			# load both arrays
			bm_id = rowOne[0]
			sql_statement = "SELECT PERIOD,PRICE_VALUE FROM PRICES_VALUES WHERE PRICES_ID = %s ORDER BY PERIOD ;"  # <-- add facility_type
			cur.execute(sql_statement, (bm_id,))
			i = 1900
			rowAll = cur.fetchall()
			for row in rowAll:
				stm = "self.bm_" + pCode + ".append(" + str(row[1]) + ")"
				eval(stm)
				if row[0] == i:
					i += 1
	
