	def formatDate(self, unformatted_date):
		formatted_date = ""
		if unformatted_date is None or unformatted_date == "NULL":
			pass
		else:
			unformatted_date = unformatted_date.strip()
		
		if unformatted_date and unformatted_date != "NULL":
			if '/' in unformatted_date:
				split_date = unformatted_date.split('/')
				year_list = [date for date in split_date if len(date) == 4]
				if len(year_list) == 1:
					year = year_list[0]
					if split_date.index(year) == 2 and len(unformatted_date) == 10:
						formatted_date = unformatted_date
					else:
						formatted_date = '01/01/' + year
			elif '-' in unformatted_date:
				split_date = unformatted_date.split('-')
				year_list = [date for date in split_date if len(date) == 4]
				if len(year_list) == 1:
					year = year_list[0]
					formatted_date = '01/01/' + year
			elif len(unformatted_date) == 4 and str(unformatted_date)[0] in ['1', '2']:
				formatted_date = '01/01/' + str(unformatted_date)
		return formatted_date
	
