							whereClause = ""
							if mStatus == 'Discovered' and self.model_discovered_fields:
								var_opex_mmcf = get_field_param(mCur, ast_id, param='variable_opex_per_mmcf')
								var_opex_mmcf_factor = self.getAuxilaryParams("VARIABLE_OPEX_PER_MMCF", mCur, ast_id,
																			  mStatus, mCountry, mConstituent, mRegion,
																			  mResource_type, mTerrain, mOperator)
								var_opex_mmcf *= var_opex_mmcf_factor
