									if mWellUnit.upper() in ["MM", "USDMILLION", "MILLION", "MIL"]:
										mFactor = 1000000
									if self.model_abandoned_uncon and mStatus == 'Abandoned':
										if int(mWellPeriod) < new_start_year:
											well_drilling[mWellPeriod] = float(mWellProd) * mFactor
										elif int(mWellPeriod) == new_start_year:
											well_drilling[mWellPeriod] = 0.0
									else:
										well_drilling[mWellPeriod] = float(mWellProd) * mFactor
