							# identify the abandonment year based on the Boe equivalent minimum across all commodities
							boe_total = sum([float(col_data[comm_col][commYear]) for comm_col in 'bcdef']) / float(
								self.days_in_year)
							
							peak_total = col_data[peak_col][commYear] / float(self.days_in_year)
							
							# ----- Tally for the CAPEX EXTRA
