	def replaceRange(self, wb2, sheetName, from_rowY, from_colX, to_rowY, to_colX, symbol):
		"""Zero out this area"""
		alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
		try:
			ws2 = wb2[sheetName]
		except:
			ws2 = wb2.get_sheet_by_name(sheetName)
		for i in range(from_rowY, to_rowY + 1):
			for j in range(from_colX, to_colX + 1):
				ws2[alphabet[i] + str(j)] = symbol
	
	# --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	def convertNull(self, var, varType):
		var_out = var
		if var is None or var == "NULL":
			var_out = ""
		else:
			if varType == 'N':
				var_out = float(var)
			elif varType == 'D':
				var_out = '=DATE("' + var[-4:] + '","' + var[:2] + '","' + var[3:5] + '")'
		return var_out
	
